import { Component } from '@angular/core';
@Component({
  selector: 'app-employee',
  templateUrl: './employee.component.html',
  styleUrls: ['./employee.component.css'],
})
export class EmployeeComponent {
  empName: string | undefined;
  employee_Name: string | undefined;
  cities = ['Delhi', 'Mumbai', 'Chennai'];

  employees = [
    { eid: 1, ename: 'Amit', contact: 1234 },
    { eid: 2, ename: 'Ram', contact: 14532 },
    { eid: 3, ename: 'Rahul', contact: 98432 },
  ];

  sendData() {
    this.empName = 'Rohit';
  }

  receiveData(data: string) {
    this.employee_Name = data;
  }

  isContactVisible: boolean = true;
  changeContactStatus() {
    this.isContactVisible = !this.isContactVisible;
  }

  age: number = 17;
}
<div style="background-color: blueviolet">
  <h1 style="color: antiquewhite">Employee Component</h1>
  <button (click)="sendData()">Send Data from Parent to Child</button>
  <app-emp-details
    [emp_Name]="empName"
    (my_event)="receiveData($event)"
  ></app-emp-details>
  <hr />
  <h3>Received Employee : {{ employee_Name }}</h3>
</div>

<br />
<br />
<hr />

<table border="1">
  <caption>
    Employee Details
  </caption>
  <thead>
    
    <th>Employee Id</th>
    
    <th>Employee Name</th>
           
    <th>Employee Contact</th>
       
  </thead>
     
  <tbody>
           
    <tr>
                 
      <td>{{ employees[0].eid }}</td>
                 
      <td>{{ employees[0].ename }}</td>
                 
      <td>{{ employees[0].contact }}</td>
             
    </tr>
           
    <tr>
                 
      <td>{{ employees[1].eid }}</td>
                 
      <td>{{ employees[1].ename }}</td>
                 
      <td>{{ employees[1].contact }}</td>
             
    </tr>
           
    <tr>
                 
      <td>{{ employees[2].eid }}</td>
                 
      <td>{{ employees[2].ename }}</td>
                 
      <td>{{ employees[2].contact }}</td>
             
    </tr>
       
  </tbody>
</table>
